        sitTargets['back_lounge_N'] = { sit: true, facing: Math.PI };
        sitTargets['back_lounge_S'] = { sit: true, facing: 0 };

        // Conversation pit (back-left)
        nodes['pit_N'] = new THREE.Vector3(-8, floorY, -6);
        nodes['pit_S'] = new THREE.Vector3(-8, floorY, -10);
        nodes['pit_E'] = new THREE.Vector3(-4, floorY, -8);
        nodes['pit_W'] = new THREE.Vector3(-12, floorY, -8);
